#!/usr/bin/env node
/**
 * U4 PROMPT COST MEASUREMENT HARNESS (443-005)
 *
 * Composes real worker prompts for a fixed corpus of real historical sprint tasks
 * (>=8 tasks, >=5 distinct primary intents — includes the four sprint-442
 * event-sourcing tasks; the same real text sprint-442-001 is pinned in
 * tests/core/word-match-intent-hygiene.test.ts) in BOTH `persona_render` modes
 * ('full' and 'guidance', ADR-G-027 / task 443-003), via the REAL production
 * compose path — `buildTaskPromptSegmented` (src/orchestra/prompt-god-template.ts)
 * — using real agent PROMPT.md files, real skill SKILL.md files, and real accepted
 * ADRs read live from `.brain/memory.db`. Not a reimplementation, not a mock.
 *
 * Output: .analysis/u4-olcum/report.md — per-prompt and average segment-byte
 * breakdown (persona / adr / skills / task-core / rest) for both modes, totals,
 * and percent deltas (guidance vs full).
 *
 * WHY THIS FILE SHELLS OUT TO TSX (read before "simplifying" this):
 * This script is invoked as plain `node scripts/measure-prompt-cost.mjs` (no
 * --loader). Plain node cannot resolve this project's Node16/nodenext ESM
 * convention (`.js`-specifier import of a sibling `.ts` source file) — verified:
 * `node file.ts` throws ERR_MODULE_NOT_FOUND for a `./sibling.js` import that only
 * exists as `./sibling.ts`. `dist/` cannot be substituted either: it predates
 * task 443-003's persona_render/guidance-mode work (dist mtime < src mtime at the
 * time of this task), and rebuilding it is forbidden mid-sprint. So the actual
 * `buildTaskPromptSegmented` call has to run under a TS-aware loader — this
 * writes a throwaway worker program to the OS tmpdir (never inside the repo — this
 * script is the only file in this task's write scope) and executes it with tsx,
 * fetched on demand via `npx` exactly like this repo's existing
 * `docs:generate-cli` package.json script already does.
 */

import {
  chmodSync,
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawn } from 'node:child_process';

const PROJECT_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const REPORT_PATH = join(PROJECT_ROOT, '.analysis', 'u4-olcum', 'report.md');
const SEGMENT_BUCKETS = ['persona', 'adr', 'skills', 'taskCore', 'rest'];
const MODES = ['full', 'guidance'];

// ─── Fixture corpus (8 real historical sprint tasks, 6 distinct primary intents) ──
// title/description/scope/goNogo/assignedAgent/assignedSkills/routingMeta copied
// verbatim from real `.brain/archive/sprints/**/task-*.json` records (that dir is
// gitignored/ephemeral, so the corpus is embedded here rather than read at
// runtime — keeps this script reproducible on any host). Base64-encoded to avoid
// any escaping hazard from the embedded Turkish task text (backticks, quotes,
// backslash-escaped separators like `\;` all appear verbatim in real goCriteria
// text) — decoded once at startup, see `loadFixtures()`.
//   442-001..004 devops(x3)/implementation(x1) — the sprint-442 event-sourcing
//     tasks named in this task's description; tests/core/word-match-intent-
//     hygiene.test.ts pins a trimmed excerpt of 442-001's text, this is the full
//     original.
//   416-001 bugfix, 415-003 security, 410-001 design, 423-002 config
const FIXTURES_B64 = '';

function loadFixtures() {
  const json = Buffer.from(FIXTURES_B64, 'base64').toString('utf-8');
  return JSON.parse(json);
}

// ─── tsx resolution (portable primary path + sandboxed-noexec-tmp fallback) ──────

/** Promise-wrapped async spawn (no spawnSync, per project convention — ADR-D-002). */
function runProcess(command, args, opts = {}) {
  return new Promise((resolvePromise) => {
    const child = spawn(command, args, { stdio: ['ignore', 'pipe', 'pipe'], ...opts });
    let stdout = '';
    let stderr = '';
    child.stdout?.on('data', (d) => { stdout += d.toString('utf-8'); });
    child.stderr?.on('data', (d) => { stderr += d.toString('utf-8'); });
    child.on('error', (err) => resolvePromise({ code: -1, stdout, stderr: stderr + String(err) }));
    child.on('close', (code) => resolvePromise({ code: code ?? -1, stdout, stderr }));
  });
}

/** Recursively copy `srcDir` into `destDir`, then chmod every file `u+x` (mirrors the source's own layout — needed so tsx's own relative resolution of sibling packages like `@esbuild/<platform>` keeps working from the copy). */
function vendorCopyExecutable(srcDir, destDir) {
  cpSync(srcDir, destDir, { recursive: true });
  const stack = [destDir];
  while (stack.length > 0) {
    const dir = stack.pop();
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) stack.push(full);
      else if (entry.isFile()) {
        try { chmodSync(full, 0o755); } catch { /* best-effort */ }
      }
    }
  }
}

/**
 * Run a script under tsx. Three tiers, each engaged only when the previous fails:
 *   1. Primary — `npx --yes tsx <script> <args>`: the standard, fully portable
 *      invocation (works unmodified on macOS/Linux/Windows/WSL — the same shape
 *      already used by this repo's `docs:generate-cli` package.json script).
 *   2. Resolve the real tsx entry point (`command -v tsx` + realpath) and invoke
 *      it via `node <entry>` — node reads the file directly, no execute bit
 *      required on the entry file itself.
 *   3. Some sandboxes mount npm's npx cache noexec at the FILESYSTEM level (not
 *      just a missing +x bit) — tier 2's `node <entry>` gets past that for the
 *      tsx entry file, but tsx internally spawns its own native `esbuild`
 *      binary as a child process, which hits the exact same noexec wall one
 *      level deeper (confirmed: `EACCES: spawn .../@esbuild/<platform>/bin/esbuild`).
 *      Fix: copy tsx's whole resolved `node_modules` tree into an executable
 *      location (inside this project — the repo checkout itself is never
 *      noexec) and chmod every file `+x` there, then run the COPY. Deleted in
 *      a `finally` before this function returns, on every path — it never
 *      persists as a project artifact.
 * Per CLAUDE.md IMMUTABLE LAW 2 (every environment): the portable path is tried
 * first and covers every real host; tiers 2-3 are a best-effort, honestly-
 * failing rescue for this narrow sandbox quirk, not a silent workaround.
 */
async function runTsx(scriptPath, args) {
  const primary = await runProcess('npx', ['--yes', '--prefer-offline', 'tsx', scriptPath, ...args]);
  if (primary.code === 0) return primary;

  const which = await runProcess('npx', ['--yes', '--prefer-offline', '-p', 'tsx', '-c', 'command -v tsx']);
  const shimPath = which.stdout.trim();
  if (which.code !== 0 || !shimPath) {
    throw new Error(
      `tsx invocation failed (portable path) and the sandbox fallback could not resolve a tsx binary.\n` +
      `Primary (npx tsx) stderr:\n${primary.stderr}\n` +
      `Fallback (resolve tsx bin) stderr:\n${which.stderr}`,
    );
  }
  let resolvedEntry;
  try {
    resolvedEntry = realpathSync(shimPath);
  } catch (e) {
    throw new Error(`Resolved tsx shim at "${shimPath}" but could not realpath it: ${e}`);
  }

  const tier2 = await runProcess('node', [resolvedEntry, scriptPath, ...args]);
  if (tier2.code === 0) return tier2;

  // Tier 3: vendor-copy the resolved node_modules tree into the executable zone.
  // resolvedEntry looks like <root>/node_modules/tsx/dist/cli.mjs.
  const nodeModulesDir = dirname(dirname(dirname(resolvedEntry)));
  if (dirname(nodeModulesDir) === nodeModulesDir || !nodeModulesDir.endsWith('node_modules')) {
    throw new Error(
      `tsx invocation failed on the portable path and both sandbox fallbacks.\n` +
      `Primary (npx tsx) stderr:\n${primary.stderr}\n` +
      `Tier-2 (node ${resolvedEntry}) stderr:\n${tier2.stderr}\n` +
      `Tier-3 skipped: could not derive a node_modules root from "${resolvedEntry}".`,
    );
  }
  const vendorDir = join(PROJECT_ROOT, `.mpc-tsx-vendor-${process.pid}`);
  try {
    vendorCopyExecutable(nodeModulesDir, join(vendorDir, 'node_modules'));
    const vendoredEntry = join(vendorDir, 'node_modules', 'tsx', 'dist', 'cli.mjs');
    const tier3 = await runProcess('node', [vendoredEntry, scriptPath, ...args]);
    if (tier3.code !== 0) {
      throw new Error(
        `tsx invocation failed on the portable path and all sandbox fallbacks.\n` +
        `Primary (npx tsx) stderr:\n${primary.stderr}\n` +
        `Tier-2 (node ${resolvedEntry}) stderr:\n${tier2.stderr}\n` +
        `Tier-3 (vendored copy) stderr:\n${tier3.stderr}`,
      );
    }
    return tier3;
  } finally {
    rmSync(vendorDir, { recursive: true, force: true });
  }
}

// ─── Worker program (executed under tsx — this is where the REAL compose path runs) ──
// Built via plain string concatenation (never a template literal) because the
// embedded fixture JSON contains literal backtick characters (inline-code spans in
// the real goCriteria text) that would otherwise prematurely close a `...` template.
function buildWorkerSource(fixturesB64) {
  const lines = [
    "import { readFileSync, existsSync, writeFileSync } from 'node:fs';",
    "import { join } from 'node:path';",
    "import { pathToFileURL } from 'node:url';",
    "",
    "const [, , projectRoot, outFile] = process.argv;",
    "",
    "const FIXTURES = JSON.parse(Buffer.from('" + fixturesB64 + "', 'base64').toString('utf-8'));",
    "",
    "async function loadReal(relPath) {",
    "  const url = pathToFileURL(join(projectRoot, relPath)).href;",
    "  return import(url);",
    "}",
    "",
    "const { buildTaskPromptSegmented } = await loadReal('src/orchestra/prompt-god-template.ts');",
    "const { MemoryStore } = await loadReal('src/core/memory-store.ts');",
    "const { BRAIN_DIR, MEMORY_DB_FILE } = await loadReal('src/core/constants.ts');",
    "const { TaskStatus } = await loadReal('src/core/task-types.ts');",
    "",
    "function loadAgentPrompt(agentId) {",
    "  const p = join(projectRoot, 'src/core/builtins/agents', agentId, 'PROMPT.md');",
    "  return existsSync(p) ? readFileSync(p, 'utf-8') : undefined;",
    "}",
    "",
    "function loadSkillPrompt(name) {",
    "  const p = join(projectRoot, 'src/core/builtins/skills', name, 'SKILL.md');",
    "  return existsSync(p) ? readFileSync(p, 'utf-8') : null;",
    "}",
    "",
    "let allAdrs;",
    "let adrSource = 'no .brain/memory.db found on this host';",
    "try {",
    "  const dbPath = join(projectRoot, BRAIN_DIR, MEMORY_DB_FILE);",
    "  if (existsSync(dbPath)) {",
    "    const store = new MemoryStore(dbPath);",
    "    try {",
    "      allAdrs = store.getByType('adr').filter((a) => a.status === 'accepted');",
    "      adrSource = 'live .brain/memory.db (' + allAdrs.length + ' accepted ADRs)';",
    "    } finally {",
    "      store.close();",
    "    }",
    "  }",
    "} catch (e) {",
    "  adrSource = 'error reading .brain/memory.db: ' + (e && e.message ? e.message : String(e));",
    "}",
    "",
    "function bucketOf(kind) {",
    "  if (kind === 'persona') return 'persona';",
    "  if (kind === 'adr') return 'adr';",
    "  if (kind === 'skills') return 'skills';",
    "  if (kind === 'task') return 'taskCore';",
    "  return 'rest';",
    "}",
    "",
    "const rows = [];",
    "const skippedSkills = new Set();",
    "",
    "for (const fx of FIXTURES) {",
    "  const agentPrompt = loadAgentPrompt(fx.assignedAgent);",
    "  const skillPrompts = [];",
    "  for (const name of fx.assignedSkills || []) {",
    "    const content = loadSkillPrompt(name);",
    "    if (content == null) { skippedSkills.add(name); continue; }",
    "    skillPrompts.push({ name, content });",
    "  }",
    "",
    "  const task = {",
    "    id: fx.id,",
    "    title: fx.title,",
    "    description: fx.description,",
    "    model: fx.model,",
    "    effort: fx.effort,",
    "    priority: fx.priority,",
    "    reason: fx.reason,",
    "    scope: fx.scope,",
    "    dependencies: fx.dependencies,",
    "    goNogo: fx.goNogo,",
    "    status: TaskStatus.PENDING,",
    "    type: fx.type,",
    "    sprintId: fx.sprintId,",
    "    forceModel: fx.forceModel,",
    "    forceEffort: fx.forceEffort,",
    "    assignedAgent: fx.assignedAgent,",
    "    assignedSkills: fx.assignedSkills,",
    "    routingMeta: fx.routingMeta,",
    "  };",
    "",
    "  const workerEffort = fx.forceEffort === 'high' ? 'high' : fx.forceEffort === 'low' ? 'low' : 'medium';",
    "",
    "  for (const mode of ['full', 'guidance']) {",
    "    const ctx = {",
    "      agentPrompt,",
    "      agentId: fx.assignedAgent,",
    "      skillPrompts,",
    "      allAdrs,",
    "      effort: workerEffort,",
    "      dependencies: fx.dependencies,",
    "      personaRenderMode: mode,",
    "    };",
    "    const { prompt, segments } = buildTaskPromptSegmented(task, ctx);",
    "    const buckets = { persona: 0, adr: 0, skills: 0, taskCore: 0, rest: 0 };",
    "    for (const seg of segments) {",
    "      const bytes = Buffer.byteLength(seg.content, 'utf-8');",
    "      buckets[bucketOf(seg.kind)] += bytes;",
    "    }",
    "    const total = Buffer.byteLength(prompt, 'utf-8');",
    "    rows.push({",
    "      taskId: fx.id,",
    "      intent: (fx.routingMeta && fx.routingMeta.taskDNA && fx.routingMeta.taskDNA.intent && fx.routingMeta.taskDNA.intent.primary) || 'unknown',",
    "      agent: fx.assignedAgent,",
    "      mode,",
    "      buckets,",
    "      total,",
    "    });",
    "  }",
    "}",
    "",
    "writeFileSync(outFile, JSON.stringify({",
    "  rows,",
    "  meta: {",
    "    adrSource,",
    "    skippedSkills: [...skippedSkills],",
    "    fixtureCount: FIXTURES.length,",
    "  },",
    "}, null, 2), 'utf-8');",
    "",
  ];
  return lines.join('\n');
}

// ─── Report rendering ─────────────────────────────────────────────────────────────

function fmt(n) {
  return n.toLocaleString('en-US');
}

function pctDelta(before, after) {
  if (before === 0) return after === 0 ? 0 : Infinity;
  return ((after - before) / before) * 100;
}

function fmtPct(p) {
  if (!Number.isFinite(p)) return 'n/a';
  const sign = p > 0 ? '+' : '';
  return `${sign}${p.toFixed(1)}%`;
}

function average(nums) {
  if (nums.length === 0) return 0;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

function buildReport(result, fixtures) {
  const { rows, meta } = result;
  const byMode = Object.fromEntries(MODES.map((m) => [m, rows.filter((r) => r.mode === m)]));

  const lines = [];
  lines.push('# U4 Prompt Cost Measurement Report');
  lines.push('');
  lines.push(
    'Generated by `scripts/measure-prompt-cost.mjs` via the REAL production compose path — ' +
    '`buildTaskPromptSegmented` (`src/orchestra/prompt-god-template.ts`), run under `tsx` ' +
    'against the actual project source (dist is stale for the guidance-mode change under ' +
    'measurement here; this is a real-binary tsx run, not a mock).',
  );
  lines.push('');
  lines.push('## Methodology');
  lines.push('');
  lines.push(`- Corpus: ${fixtures.length} real historical sprint tasks (title/description/scope/goNogo/` +
    'assignedAgent/assignedSkills/routingMeta copied verbatim from real `.brain/archive/sprints/**/task-*.json` ' +
    'records), spanning distinct primary intents:');
  const intentCounts = new Map();
  for (const fx of fixtures) {
    const intent = fx.routingMeta?.taskDNA?.intent?.primary ?? 'unknown';
    intentCounts.set(intent, (intentCounts.get(intent) ?? 0) + 1);
  }
  for (const [intent, count] of [...intentCounts.entries()].sort()) {
    lines.push(`  - ${intent}: ${count}`);
  }
  lines.push(`- ADRs: ${meta.adrSource} (real \`getByType('adr')\` call, same as production \`task-builder.ts\` \`buildWorkerPrompt\`).`);
  lines.push('- Agent personas: real `src/core/builtins/agents/<id>/PROMPT.md` files.');
  lines.push('- Skills: real `src/core/builtins/skills/<name>/SKILL.md` files' +
    (meta.skippedSkills.length > 0
      ? `; ${meta.skippedSkills.length} assigned skill(s) skipped — no static SKILL.md file (dynamically-resolved at runtime, not measurable here): ${meta.skippedSkills.join(', ')}.`
      : '.'));
  lines.push('- Segment bytes = UTF-8 byte length of each `PromptSegment.content`, bucketed by `kind`: ' +
    '`persona`→persona, `adr`→adr, `skills`→skills, `task`→task-core, everything else (worker-contract, ' +
    'verify-steps, verify-precedence, npm-advisory, karpathy, what-to-do, heartbeat, result-contract, smoke, ' +
    'scope, goNogo, deps, shared, handoff, comms)→rest.');
  lines.push('- Both `persona_render` modes (`full`, `guidance`) composed for every fixture task with an ' +
    'otherwise byte-identical `SprintContext` (same agent prompt, same skills, same ADRs, same effort).');
  lines.push('');

  lines.push('## Corpus');
  lines.push('');
  lines.push('| Task | Intent | Agent | Skills |');
  lines.push('| --- | --- | --- | --- |');
  for (const fx of fixtures) {
    const intent = fx.routingMeta?.taskDNA?.intent?.primary ?? 'unknown';
    lines.push(`| ${fx.id} | ${intent} | ${fx.assignedAgent} | ${(fx.assignedSkills ?? []).join(', ') || '(none)'} |`);
  }
  lines.push('');

  for (const mode of MODES) {
    lines.push(`## Per-Prompt Segment Breakdown — \`${mode}\` mode (bytes)`);
    lines.push('');
    lines.push('| Task | persona | adr | skills | task-core | rest | total |');
    lines.push('| --- | ---: | ---: | ---: | ---: | ---: | ---: |');
    for (const r of byMode[mode]) {
      lines.push(
        `| ${r.taskId} | ${fmt(r.buckets.persona)} | ${fmt(r.buckets.adr)} | ${fmt(r.buckets.skills)} | ` +
        `${fmt(r.buckets.taskCore)} | ${fmt(r.buckets.rest)} | ${fmt(r.total)} |`,
      );
    }
    const avgBuckets = Object.fromEntries(
      SEGMENT_BUCKETS.map((b) => [b, average(byMode[mode].map((r) => r.buckets[b]))]),
    );
    const avgTotal = average(byMode[mode].map((r) => r.total));
    lines.push(
      `| **Average** | ${fmt(Math.round(avgBuckets.persona))} | ${fmt(Math.round(avgBuckets.adr))} | ` +
      `${fmt(Math.round(avgBuckets.skills))} | ${fmt(Math.round(avgBuckets.taskCore))} | ` +
      `${fmt(Math.round(avgBuckets.rest))} | ${fmt(Math.round(avgTotal))} |`,
    );
    lines.push('');
  }

  lines.push('## Percent Delta — `guidance` vs `full` (per task)');
  lines.push('');
  lines.push('| Task | persona Δ | adr Δ | skills Δ | task-core Δ | rest Δ | total Δ |');
  lines.push('| --- | ---: | ---: | ---: | ---: | ---: | ---: |');
  const byTaskId = new Map();
  for (const r of rows) {
    if (!byTaskId.has(r.taskId)) byTaskId.set(r.taskId, {});
    byTaskId.get(r.taskId)[r.mode] = r;
  }
  for (const fx of fixtures) {
    const pair = byTaskId.get(fx.id);
    const full = pair.full;
    const guidance = pair.guidance;
    const deltas = SEGMENT_BUCKETS.map((b) => pctDelta(full.buckets[b], guidance.buckets[b]));
    const totalDelta = pctDelta(full.total, guidance.total);
    lines.push(
      `| ${fx.id} | ${deltas.map(fmtPct).join(' | ')} | ${fmtPct(totalDelta)} |`,
    );
  }
  const avgFullBuckets = Object.fromEntries(
    SEGMENT_BUCKETS.map((b) => [b, average(byMode.full.map((r) => r.buckets[b]))]),
  );
  const avgGuidanceBuckets = Object.fromEntries(
    SEGMENT_BUCKETS.map((b) => [b, average(byMode.guidance.map((r) => r.buckets[b]))]),
  );
  const avgFullTotal = average(byMode.full.map((r) => r.total));
  const avgGuidanceTotal = average(byMode.guidance.map((r) => r.total));
  const avgDeltas = SEGMENT_BUCKETS.map((b) => pctDelta(avgFullBuckets[b], avgGuidanceBuckets[b]));
  const avgTotalDelta = pctDelta(avgFullTotal, avgGuidanceTotal);
  lines.push(
    `| **Average** | ${avgDeltas.map(fmtPct).join(' | ')} | ${fmtPct(avgTotalDelta)} |`,
  );
  lines.push('');

  lines.push('## Totals (corpus-wide sum, all 8 prompts per mode)');
  lines.push('');
  const sumFull = byMode.full.reduce((a, r) => a + r.total, 0);
  const sumGuidance = byMode.guidance.reduce((a, r) => a + r.total, 0);
  lines.push(`- \`full\` mode total: ${fmt(sumFull)} bytes`);
  lines.push(`- \`guidance\` mode total: ${fmt(sumGuidance)} bytes`);
  lines.push(`- Corpus-wide delta: ${fmtPct(pctDelta(sumFull, sumGuidance))}`);
  lines.push('');

  lines.push('## Findings');
  lines.push('');
  const avgAdrGuidanceBytes = avgGuidanceBuckets.adr;
  if (avgAdrGuidanceBytes > 1024) {
    lines.push(
      `- **Remaining gap**: the measured ADR segment average in \`guidance\` mode is ` +
      `${fmt(Math.round(avgAdrGuidanceBytes))} bytes (${(avgAdrGuidanceBytes / 1024).toFixed(2)}KB), which ` +
      `exceeds the 1KB threshold. \`guidance\` mode (task 443-003) only condenses the AGENT PERSONA block — ` +
      `the ADR block is rendered independently (\`buildAdrBlock\`, unaffected by \`personaRenderMode\`) and ` +
      `still carries the operative-ADR full body (PCOMP-W4 tiering: only the non-governing ADRs are condensed; ` +
      `the governing/explicit-ref ADR keeps its full Decision body). This is a genuine remaining cost surface, ` +
      `distinct from the persona-render work this task measures — **not patched here** per this task's scope.`,
    );
  } else {
    lines.push(
      `- ADR segment average in \`guidance\` mode (${fmt(Math.round(avgAdrGuidanceBytes))} bytes) is within the 1KB threshold.`,
    );
  }
  lines.push(
    `- Persona segment delta (guidance vs full) averages ${fmtPct(avgDeltas[0])} — this is the primary effect ` +
    `task 443-003's guidance-mode render is expected to produce.`,
  );
  if (meta.skippedSkills.length > 0) {
    lines.push(
      `- ${meta.skippedSkills.length} assigned skill(s) have no static \`SKILL.md\` file and were excluded from ` +
      `every measured prompt (both modes, symmetric — does not bias the delta): ${meta.skippedSkills.join(', ')}.`,
    );
  }
  lines.push('');

  return lines.join('\n');
}

// ─── Main ──────────────────────────────────────────────────────────────────────────

async function main() {
  const fixtures = loadFixtures();
  if (fixtures.length < 8) {
    throw new Error(`Corpus has only ${fixtures.length} tasks — need at least 8.`);
  }
  const intents = new Set(fixtures.map((fx) => fx.routingMeta?.taskDNA?.intent?.primary ?? 'unknown'));
  if (intents.size < 5) {
    throw new Error(`Corpus spans only ${intents.size} distinct intents (${[...intents].join(', ')}) — need at least 5.`);
  }

  const tmpDir = mkdtempSync(join(tmpdir(), 'measure-prompt-cost-'));
  const workerPath = join(tmpDir, 'compose-worker.mjs');
  const outPath = join(tmpDir, 'result.json');
  writeFileSync(workerPath, buildWorkerSource(FIXTURES_B64), 'utf-8');

  try {
    console.log(`[measure-prompt-cost] running real compose path via tsx for ${fixtures.length} tasks x ${MODES.length} modes...`);
    await runTsx(workerPath, [PROJECT_ROOT, outPath]);

    if (!existsSync(outPath)) {
      throw new Error('tsx worker exited 0 but did not write the result file.');
    }
    const result = JSON.parse(readFileSync(outPath, 'utf-8'));
    if (!Array.isArray(result.rows) || result.rows.length !== fixtures.length * MODES.length) {
      throw new Error(
        `Expected ${fixtures.length * MODES.length} rows (${fixtures.length} tasks x ${MODES.length} modes), got ${result.rows?.length ?? 0}.`,
      );
    }

    const report = buildReport(result, fixtures);
    mkdirSync(dirname(REPORT_PATH), { recursive: true });
    writeFileSync(REPORT_PATH, report, 'utf-8');
    console.log(`[measure-prompt-cost] wrote ${REPORT_PATH}`);
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }
}

main().catch((err) => {
  console.error('[measure-prompt-cost] FAILED:', err && err.stack ? err.stack : err);
  process.exitCode = 1;
});
